1	//! Model pricing table — cost per million tokens (MTok).
2	//!
3	//! Bundled pricing comes from `data/model-pricing.toml` (compiled in via
4	//! `include_str!`). Users can override by placing their own TOML at
5	//! `~/.config/rtk/model-pricing.toml`.
6	
7	use anyhow::Result;
8	use serde::Deserialize;
9	use std::collections::HashMap;
10	
11	const BUNDLED_PRICING: &str = include_str!("../../data/model-pricing.toml");
12	const USER_PRICING_PATH: &str = "rtk/model-pricing.toml";
13	
14	#[derive(Debug, Clone, Deserialize)]
15	pub struct ModelPricing {
16	    pub input_per_mtok: f64,
17	    pub output_per_mtok: f64,
18	    #[serde(default)]
19	    pub cache_read_per_mtok: f64,
20	    #[serde(default)]
21	    pub cache_write_per_mtok: f64,
22	}
23	
24	#[derive(Debug, Deserialize)]
25	struct PricingFile {
26	    models: HashMap<String, ModelPricing>,
27	}
28	
29	pub struct PricingTable {
30	    models: HashMap<String, ModelPricing>,
31	}
32	
33	impl PricingTable {
34	    /// Load pricing: user override wins, falls back to bundled.
35	    pub fn load() -> Self {
36	        // Try user override first
37	        if let Some(p) = user_pricing_path() {
38	            if let Ok(text) = std::fs::read_to_string(&p) {
39	                if let Ok(table) = Self::parse(&text) {
40	                    return table;
41	                }
42	            }
43	        }
44	        // Bundled is always parseable — unwrap is safe here.
45	        Self::parse(BUNDLED_PRICING).unwrap_or_else(|_| Self {
46	            models: HashMap::new(),
47	        })
48	    }
49	
50	    fn parse(toml_text: &str) -> Result<Self> {
51	        let file: PricingFile = toml::from_str(toml_text)?;
52	        Ok(Self {
53	            models: file.models,
54	        })
55	    }
56	
57	    /// Look up pricing for a model ID using fuzzy prefix matching.
58	    ///
59	    /// "claude-opus-4-20250514" matches the "claude-opus-4" entry because
60	    /// the model_id starts with the catalog key (or vice-versa).
61	    pub fn get(&self, model_id: &str) -> Option<&ModelPricing> {
62	        // Exact match first
63	        if let Some(p) = self.models.get(model_id) {
64	            return Some(p);
65	        }
66	
67	        // Fuzzy: catalog key is a prefix of the queried model_id
68	        // e.g. key="claude-opus-4" matches "claude-opus-4-20250514"
69	        for (key, pricing) in &self.models {
70	            if model_id.starts_with(key.as_str()) || key.starts_with(model_id) {
71	                return Some(pricing);
72	            }
73	        }
74	
75	        None
76	    }
77	
78	    /// Compute median pricing across all known models (fallback for unknowns).
79	    fn median_pricing(&self) -> ModelPricing {
80	        let mut inputs: Vec<f64> = self.models.values().map(|m| m.input_per_mtok).collect();
81	        let mut outputs: Vec<f64> = self.models.values().map(|m| m.output_per_mtok).collect();
82	        inputs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
83	        outputs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
84	        let mid = inputs.len() / 2;
85	        ModelPricing {
86	            input_per_mtok: inputs.get(mid).copied().unwrap_or(3.0),
87	            output_per_mtok: outputs.get(mid).copied().unwrap_or(15.0),
88	            cache_read_per_mtok: 0.3,
89	            cache_write_per_mtok: 3.75,
90	        }
91	    }
92	}
93	
94	/// Calculate cost in USD for a given model and token counts.
95	///
96	/// Falls back to median pricing when `model_id` is unknown, and logs a
97	/// warning to stderr so callers can see the degraded result.
98	pub fn cost_for_tokens(
99	    model_id: &str,
100	    input: u64,
101	    output: u64,
102	    cache_read: u64,
103	    cache_write: u64,
104	) -> f64 {
105	    let table = PricingTable::load();
106	    let pricing = table.get(model_id).cloned().unwrap_or_else(|| {
107	        eprintln!(
108	            "[rtk cost] unknown model '{}', using median pricing",
109	            model_id
110	        );
111	        table.median_pricing()
112	    });
113	
114	    tokens_to_usd(&pricing, input, output, cache_read, cache_write)
115	}
116	
117	fn tokens_to_usd(
118	    p: &ModelPricing,
119	    input: u64,
120	    output: u64,
121	    cache_read: u64,
122	    cache_write: u64,
123	) -> f64 {
124	    let mtok = 1_000_000.0_f64;
125	    (input as f64 / mtok) * p.input_per_mtok
126	        + (output as f64 / mtok) * p.output_per_mtok
127	        + (cache_read as f64 / mtok) * p.cache_read_per_mtok
128	        + (cache_write as f64 / mtok) * p.cache_write_per_mtok
129	}
130	
131	fn user_pricing_path() -> Option<std::path::PathBuf> {
132	    dirs::config_dir().map(|d| d.join(USER_PRICING_PATH))
133	}
134	
