1	//! Git branch → PR/feature linkage for cost attribution.
2	//!
3	//! All detection is <1ms: env vars + branch name only.
4	//! No network calls — this runs in the hook hot path.
5	
6	use std::process::Command;
7	
8	/// Detect a PR reference from the environment or current git branch.
9	///
10	/// Detection order:
11	/// 1. `GH_PR_NUMBER` / `GITHUB_PR_NUMBER` env vars (CI push events)
12	/// 2. `CI_MERGE_REQUEST_IID` (GitLab CI)
13	/// 3. Git branch name: `feat/PROJ-123-description` → `PROJ-123`
14	/// 4. Most recent commit subject: `fix something (#456)` → `#456`
15	pub fn detect_pr_ref() -> Option<String> {
16	    // 1. GitHub env vars
17	    if let Ok(n) = std::env::var("GH_PR_NUMBER") {
18	        let n = n.trim().to_string();
19	        if !n.is_empty() {
20	            return Some(format!("#{}", n));
21	        }
22	    }
23	    if let Ok(n) = std::env::var("GITHUB_PR_NUMBER") {
24	        let n = n.trim().to_string();
25	        if !n.is_empty() {
26	            return Some(format!("#{}", n));
27	        }
28	    }
29	
30	    // 2. GitLab env var
31	    if let Ok(iid) = std::env::var("CI_MERGE_REQUEST_IID") {
32	        let iid = iid.trim().to_string();
33	        if !iid.is_empty() {
34	            return Some(format!("!{}", iid));
35	        }
36	    }
37	
38	    // 3. Branch name heuristic
39	    if let Some(pr) = pr_from_branch() {
40	        return Some(pr);
41	    }
42	
43	    // 4. Recent commit message
44	    pr_from_commit()
45	}
46	
47	/// Extract a ticket / PR ref from the current git branch name.
48	///
49	/// Supported patterns:
50	/// - `feat/PROJ-123-some-desc`   → `PROJ-123`
51	/// - `fix/123-some-desc`         → `#123`
52	/// - `pr/456`                    → `#456`
53	pub fn pr_from_branch() -> Option<String> {
54	    let branch = current_branch()?;
55	    parse_branch_ref(&branch)
56	}
57	
58	/// Extract a PR number from the most recent commit subject line.
59	///
60	/// Matches `(#123)` at the end of the subject (GitHub merge-commit style).
61	pub fn pr_from_commit() -> Option<String> {
62	    let output = Command::new("git")
63	        .args(["log", "-1", "--format=%s"])
64	        .output()
65	        .ok()?;
66	
67	    if !output.status.success() {
68	        return None;
69	    }
70	
71	    let subject = String::from_utf8_lossy(&output.stdout);
72	    parse_commit_pr(subject.trim())
73	}
74	
75	/// Derive a feature tag from the git branch prefix.
76	///
77	/// `feat/auth-refactor` → `feat`
78	/// `fix/login-bug`      → `fix`
79	/// `main`               → `None`
80	pub fn detect_feature_tag() -> Option<String> {
81	    let branch = current_branch()?;
82	    // Branch format: `<prefix>/<rest>` where prefix is a known type
83	    let (prefix, _) = branch.split_once('/')?;
84	    let known = ["feat", "fix", "chore", "docs", "refactor", "test", "perf", "ci"];
85	    if known.contains(&prefix) {
86	        Some(prefix.to_string())
87	    } else {
88	        None
89	    }
90	}
91	
92	// ── Helpers ──────────────────────────────────────────────────────────────────
93	
94	fn current_branch() -> Option<String> {
95	    // HEAD may be detached in CI; fall back to GITHUB_HEAD_REF / CI_COMMIT_BRANCH
96	    if let Ok(b) = std::env::var("GITHUB_HEAD_REF") {
97	        let b = b.trim().to_string();
98	        if !b.is_empty() {
99	            return Some(b);
100	        }
101	    }
102	    if let Ok(b) = std::env::var("CI_COMMIT_BRANCH") {
103	        let b = b.trim().to_string();
104	        if !b.is_empty() {
105	            return Some(b);
106	        }
107	    }
108	
109	    let output = Command::new("git")
110	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
111	        .output()
112	        .ok()?;
113	
114	    if !output.status.success() {
115	        return None;
116	    }
117	    let branch = String::from_utf8_lossy(&output.stdout).trim().to_string();
118	    if branch.is_empty() || branch == "HEAD" {
119	        None
120	    } else {
121	        Some(branch)
122	    }
123	}
124	
125	/// Parse a Jira-style ticket or numeric PR ref from a branch name string.
126	pub(crate) fn parse_branch_ref(branch: &str) -> Option<String> {
127	    // Strip optional `<prefix>/` prefix
128	    let rest = branch.splitn(2, '/').last().unwrap_or(branch);
129	
130	    // Match Jira-style: PROJ-123 (uppercase letters, dash, digits) at start of segment
131	    let jira_re = lazy_regex!(r"([A-Z][A-Z0-9]+-\d+)");
132	    if let Some(m) = jira_re.find(rest) {
133	        return Some(m.as_str().to_string());
134	    }
135	
136	    // Match pure numeric: `pr/456` or `fix/456-description`
137	    let numeric_re = lazy_regex!(r"^(\d+)(?:-|$)");
138	    if let Some(caps) = numeric_re.captures(rest) {
139	        return Some(format!("#{}", &caps[1]));
140	    }
141	
142	    None
143	}
144	
145	/// Parse a PR number from a commit subject like `Fix login (#123)`.
146	pub(crate) fn parse_commit_pr(subject: &str) -> Option<String> {
147	    let re = lazy_regex!(r"\(#(\d+)\)\s*$");
148	    re.captures(subject)
149	        .map(|caps| format!("#{}", &caps[1]))
150	}
151	
152	/// Declare a module-local lazy regex — avoids pulling in the `lazy_regex` crate.
153	macro_rules! lazy_regex {
154	    ($pat:expr) => {{
155	        use std::sync::OnceLock;
156	        static RE: OnceLock<regex::Regex> = OnceLock::new();
157	        RE.get_or_init(|| regex::Regex::new($pat).expect("invalid regex"))
158	    }};
159	}
160	use lazy_regex;
161	
