255	fn map_record(row: &rusqlite::Row<'_>) -> rusqlite::Result<CostRecord> {
256	    Ok(CostRecord {
257	        id: Some(row.get(0)?),
258	        session_id: row.get(1)?,
259	        model_id: row.get(2)?,
260	        input_tokens: row.get::<_, i64>(3)? as u64,
261	        output_tokens: row.get::<_, i64>(4)? as u64,
262	        cache_read_tokens: row.get::<_, i64>(5)? as u64,
263	        cache_write_tokens: row.get::<_, i64>(6)? as u64,
264	        cost_usd: row.get(7)?,
265	        pr_ref: row.get(8)?,
266	        feature_tag: row.get(9)?,
267	        project_path: row.get(10)?,
268	        developer_id: row.get(11)?,
269	        timestamp: row.get(12)?,
270	    })
271	}
272	
273	fn collect_records(
274	    stmt: &mut rusqlite::Statement<'_>,
275	    params: impl rusqlite::Params,
276	) -> Result<Vec<CostRecord>> {
277	    let rows = stmt
278	        .query_map(params, map_record)?
279	        .collect::<std::result::Result<Vec<_>, _>>()?;
280	    Ok(rows)
281	}
282	
283	fn collect_summaries(stmt: &mut rusqlite::Statement<'_>) -> Result<Vec<CostSummary>> {
284	    let rows = stmt
285	        .query_map([], |row| {
286	            Ok(CostSummary {
287	                key: row.get(0)?,
288	                total_cost_usd: row.get(1)?,
289	                record_count: row.get::<_, i64>(2)? as u64,
290	                input_tokens: row.get::<_, i64>(3)? as u64,
291	                output_tokens: row.get::<_, i64>(4)? as u64,
292	            })
293	        })?
294	        .collect::<std::result::Result<Vec<_>, _>>()?;
295	    Ok(rows)
296	}
