1	//! `rtk codeflow cost` — cost attribution report for the current project.
2	//!
3	//! Subcommands:
4	//!   codeflow cost                  — project summary
5	//!   codeflow cost --by pr          — breakdown by PR
6	//!   codeflow cost --by dev         — breakdown by developer
7	//!   codeflow cost --by model       — breakdown by model
8	//!   codeflow cost --by day         — daily trend
9	//!   codeflow cost --pr <ref>       — specific PR detail
10	//!   codeflow cost --json           — machine-readable JSON
11	
12	use anyhow::{Context, Result};
13	use colored::Colorize;
14	
15	use crate::core::cost_store::{CostStore, CostSummary};
16	
17	pub fn run_cost(
18	    by: Option<&str>,
19	    pr: Option<&str>,
20	    json: bool,
21	) -> Result<()> {
22	    let store = CostStore::new().context("failed to open cost store")?;
23	
24	    // --pr <ref>: single PR detail view
25	    if let Some(pr_ref) = pr {
26	        return show_pr_detail(&store, pr_ref, json);
27	    }
28	
29	    // --by <grouping>
30	    match by {
31	        Some("pr")    => show_by_pr(&store, json),
32	        Some("dev")   => show_by_dev(&store, json),
33	        Some("model") => show_by_model(&store, json),
34	        Some("day")   => show_by_day(&store, json),
35	        Some(other)   => anyhow::bail!(
36	            "unknown grouping '{}'. Use: pr, dev, model, day", other
37	        ),
38	        None => show_summary(&store, json),
39	    }
40	}
41	
42	// ── Summary view ──────────────────────────────────────────────────────────────
43	
44	fn show_summary(store: &CostStore, json: bool) -> Result<()> {
45	    let total = store.total_cost(None)?;
46	    let by_model = store.summarize_by_model()?;
47	    let by_pr = store.summarize_by_pr()?;
48	
49	    if json {
50	        let out = serde_json::json!({
51	            "total_cost_usd": total,
52	            "by_model": by_model,
53	            "by_pr": by_pr,
54	        });
55	        println!("{}", serde_json::to_string_pretty(&out)?);
56	        return Ok(());
57	    }
58	
59	    println!("{}", "Cost Attribution Summary".bold());
60	    println!("{}", "─".repeat(50));
61	    println!("  Total: {}", format_usd(total).green().bold());
62	    println!();
63	
64	    if !by_model.is_empty() {
65	        println!("{}", "By Model:".bold());
66	        for s in &by_model {
67	            println!(
68	                "  {:40} {} ({} sessions)",
69	                truncate(&s.key, 40),
70	                format_usd(s.total_cost_usd).yellow(),
71	                s.record_count,
72	            );
73	        }
74	        println!();
75	    }
76	
77	    if !by_pr.is_empty() {
78	        println!("{}", "By PR (top 5):".bold());
79	        for s in by_pr.iter().take(5) {
80	            println!(
81	                "  {:20} {}",
82	                truncate(&s.key, 20),
83	                format_usd(s.total_cost_usd).cyan(),
84	            );
85	        }
86	    }
87	
88	    if by_model.is_empty() && by_pr.is_empty() {
89	        println!("No cost records found.");
90	        println!("Run sessions with RTK_COST_TRACK=1 to start recording.");
91	    }
92	
93	    Ok(())
94	}
