1	//! Processes incoming hook calls from AI agents and rewrites commands on the fly.
2	//!
3	//! Uses `writeln!(stdout, ...)` instead of `println!` — accidental stdout/stderr
4	//! corrupts the JSON protocol (Claude Code bug #4669 silently disables the hook).
5	
6	use super::constants::PRE_TOOL_USE_KEY;
7	use super::permissions::{self, PermissionVerdict};
8	use anyhow::{Context, Result};
9	use serde_json::{json, Value};
10	use std::io::{self, Read, Write};
11	
12	use crate::core::content_hash;
13	use crate::core::pr_linker;
14	use crate::core::provenance::{self, ProvenanceStore};
15	use crate::discover::registry::{has_heredoc, rewrite_command};
16	
17	const STDIN_CAP: usize = 1_048_576; // 1 MiB
18	
19	fn read_stdin_limited() -> Result<String> {
20	    let mut input = String::new();
21	    io::stdin()
22	        .take((STDIN_CAP + 1) as u64)
23	        .read_to_string(&mut input)
24	        .context("Failed to read stdin")?;
25	    if input.len() > STDIN_CAP {
26	        anyhow::bail!("hook stdin exceeds {} byte limit", STDIN_CAP);
27	    }
28	    Ok(input)
29	}
30	
31	// ── Copilot hook (VS Code + Copilot CLI) ──────────────────────
32	
33	/// Format detected from the preToolUse JSON input.
34	enum HookFormat {
35	    /// VS Code Copilot Chat / Claude Code: `tool_name` + `tool_input.command`, supports `updatedInput`.
36	    VsCode { command: String },
37	    /// GitHub Copilot CLI: camelCase `toolName` + `toolArgs` (JSON string), supports `modifiedArgs` for transparent rewrite.
38	    /// Carries the full parsed `toolArgs` object so we can rewrite `command` while preserving
39	    /// host-supplied metadata (description, initial_wait, mode, …) the tool requires.
40	    CopilotCli { command: String, args: Value },
41	    /// Non-bash tool, already uses rtk, or unknown format — pass through silently.
42	    PassThrough,
43	}
44	
45	/// Run the Copilot preToolUse hook.
46	/// Auto-detects VS Code Copilot Chat vs Copilot CLI format.
47	pub fn run_copilot() -> Result<()> {
48	    let input = read_stdin_limited()?;
49	
50	    // Strip leading BOM(s) before trimming: some Windows hosts prepend UTF-8
51	    // BOMs to hook stdin (confirmed for Cursor), which serde_json rejects.
52	    let input = strip_leading_bom(&input).trim();
53	    if input.is_empty() {
54	        return Ok(());
55	    }
56	
57	    let v: Value = match serde_json::from_str(input) {
58	        Ok(v) => v,
59	        Err(e) => {
60	            let _ = writeln!(io::stderr(), "[rtk hook] Failed to parse JSON input: {e}");
61	            return Ok(());
62	        }
63	    };
64	
65	    match detect_format(&v) {
66	        HookFormat::VsCode { command } => handle_vscode(&command),
67	        HookFormat::CopilotCli { command, args } => handle_copilot_cli(&command, &args),
68	        HookFormat::PassThrough => Ok(()),
69	    }
70	}
71	
72	fn detect_format(v: &Value) -> HookFormat {
73	    // VS Code Copilot Chat / Claude Code: snake_case keys
74	    if let Some(tool_name) = v.get("tool_name").and_then(|t| t.as_str()) {
75	        if matches!(tool_name, "runTerminalCommand" | "Bash" | "bash") {
76	            if let Some(cmd) = v
77	                .pointer("/tool_input/command")
78	                .and_then(|c| c.as_str())
79	                .filter(|c| !c.is_empty())
80	            {
81	                return HookFormat::VsCode {
82	                    command: cmd.to_string(),
83	                };
84	            }
85	        }
86	        return HookFormat::PassThrough;
87	    }
88	
89	    // Copilot CLI: camelCase keys, toolArgs is a JSON-encoded string
90	    if let Some(tool_name) = v.get("toolName").and_then(|t| t.as_str()) {
91	        if tool_name == "bash" {
92	            if let Some(tool_args_str) = v.get("toolArgs").and_then(|t| t.as_str()) {
93	                if let Ok(tool_args) = serde_json::from_str::<Value>(tool_args_str) {
94	                    if let Some(cmd) = tool_args
95	                        .get("command")
96	                        .and_then(|c| c.as_str())
97	                        .filter(|c| !c.is_empty())
98	                    {
99	                        return HookFormat::CopilotCli {
100	                            command: cmd.to_string(),
101	                            args: tool_args,
102	                        };
103	                    }
104	                }
105	            }
106	        }
107	        return HookFormat::PassThrough;
108	    }
109	
110	    HookFormat::PassThrough
111	}
112	
113	fn get_rewritten(cmd: &str) -> Option<String> {
114	    if has_heredoc(cmd) {
115	        return None;
116	    }
117	
118	    let (excluded, transparent_prefixes) = crate::core::config::Config::load()
119	        .map(|c| (c.hooks.exclude_commands, c.hooks.transparent_prefixes))
120	        .unwrap_or_default();
121	
122	    let rewritten = rewrite_command(cmd, &excluded, &transparent_prefixes)?;
123	
124	    if rewritten == cmd {
125	        return None;
126	    }
127	
128	    Some(rewritten)
129	}
130	
131	fn handle_vscode(cmd: &str) -> Result<()> {
132	    let verdict = permissions::check_command(cmd);
133	    if verdict == PermissionVerdict::Deny {
134	        audit_log("deny", cmd, "");
135	        return Ok(());
136	    }
137	
138	    let rewritten = match get_rewritten(cmd) {
139	        Some(r) => r,
140	        None => return Ok(()),
141	    };
142	
143	    // Allow (explicit rule matched): auto-allow the rewritten command.
144	    // Ask/Default (no allow rule matched): rewrite but let the host tool prompt.
145	    let decision = match verdict {
146	        PermissionVerdict::Allow => "allow",
147	        _ => "ask",
148	    };
149	
150	    audit_log("rewrite", cmd, &rewritten);
151	
152	    let output = json!({
153	        "hookSpecificOutput": {
154	            "hookEventName": PRE_TOOL_USE_KEY,
155	            "permissionDecision": decision,
156	            "permissionDecisionReason": "RTK auto-rewrite",
157	            "updatedInput": { "command": rewritten }
158	        }
159	    });
160	    let _ = writeln!(io::stdout(), "{output}");
161	    Ok(())
162	}
163	
164	fn handle_copilot_cli(cmd: &str, args: &Value) -> Result<()> {
165	    if let Some(response) = copilot_cli_response(cmd, args) {
166	        let _ = writeln!(io::stdout(), "{response}");
167	    }
168	    Ok(())
169	}
170	
171	fn copilot_cli_response(cmd: &str, args: &Value) -> Option<Value> {
172	    copilot_cli_response_for_verdict(cmd, args, permissions::check_command(cmd))
173	}
174	
175	fn copilot_cli_response_for_verdict(
176	    cmd: &str,
177	    args: &Value,
178	    verdict: PermissionVerdict,
179	) -> Option<Value> {
180	    if verdict == PermissionVerdict::Deny {
181	        audit_log("deny", cmd, "");
182	        return None;
183	    }
184	    let rewritten = get_rewritten(cmd)?;
185	    audit_log("rewrite", cmd, &rewritten);
186	
187	    let mut modified = args.clone();
188	    if let Some(obj) = modified.as_object_mut() {
189	        obj.insert("command".into(), Value::String(rewritten));
190	    }
191	
192	    // Copilot CLI v1.0.54 only applies `modifiedArgs` when permissionDecision is
193	    // either "allow" or absent. Omitting permissionDecision lets Copilot's normal
194	    // permission flow run on the rewritten command — `rtk *` is not on its
195	    // auto-allow list, so the user sees a prompt for the rewritten command.
196	    let mut response = json!({
197	        "permissionDecisionReason": "RTK auto-rewrite",
198	        "modifiedArgs": modified,
199	    });
200	    if verdict == PermissionVerdict::Allow {
201	        response["permissionDecision"] = json!("allow");
202	    }
203	    Some(response)
204	}
