273	/// Best-effort audit log when RTK_HOOK_AUDIT=1.
274	fn audit_log(action: &str, original: &str, rewritten: &str) {
275	    if std::env::var("RTK_HOOK_AUDIT").as_deref() != Ok("1") {
276	        return;
277	    }
278	    let _ = audit_log_inner(action, original, rewritten);
279	}
