521	fn run_cursor_inner_with_rules(
522	    input: &str,
523	    deny_rules: &[String],
524	    ask_rules: &[String],
525	    allow_rules: &[String],
526	) -> String {
527	    let input = strip_leading_bom(input);
528	    let v: Value = match serde_json::from_str(input) {
529	        Ok(v) => v,
530	        Err(_) => return "{}".to_string(),
531	    };
532	
533	    let cmd = match v
534	        .pointer("/tool_input/command")
535	        .and_then(|c| c.as_str())
536	        .filter(|c| !c.is_empty())
537	    {
538	        Some(c) => c.to_string(),
539	        None => return "{}".to_string(),
540	    };
541	
542	    let verdict = permissions::check_command_with_rules(&cmd, deny_rules, ask_rules, allow_rules);
543	    if verdict == PermissionVerdict::Deny {
544	        return "{}".to_string();
545	    }
546	
547	    match get_rewritten(&cmd) {
548	        Some(rewritten) => {
549	            let decision = "allow";
550	            let output = json!({
551	                "continue": true,
552	                "permission": decision,
553	                "updated_input": { "command": rewritten }
554	            });
555	            output.to_string()
556	        }
557	        None => "{}".to_string(),
558	    }
559	}
