561	// ── PR metadata capture ────────────────────────────────────────
562	//
563	// Detect the current PR/feature context from env vars or branch name (<1ms,
564	// no network calls) and write it to a per-session sidecar file. The cost
565	// attribution command reads these files to link sessions to PRs.
566	
567	fn capture_pr_metadata_best_effort(session_id: &str) {
568	    if std::env::var("RTK_PROVENANCE").as_deref() == Ok("0") {
569	        return;
570	    }
571	    if let Err(e) = capture_pr_metadata(session_id) {
572	        let _ = writeln!(io::stderr(), "[rtk pr-meta] {e}");
573	    }
574	}
575	
576	fn capture_pr_metadata(session_id: &str) -> anyhow::Result<()> {
577	    let pr_ref = pr_linker::detect_pr_ref();
578	    let feature_tag = pr_linker::detect_feature_tag();
579	
580	    // Nothing to record if both are absent
581	    if pr_ref.is_none() && feature_tag.is_none() {
582	        return Ok(());
583	    }
584	
585	    let data_dir = dirs::data_local_dir()
586	        .unwrap_or_else(|| std::path::PathBuf::from("."))
587	        .join(crate::core::constants::RTK_DATA_DIR)
588	        .join("session-meta");
589	
590	    std::fs::create_dir_all(&data_dir)?;
591	
592	    let meta_path = data_dir.join(format!("{}.json", session_id));
593	
594	    // Skip write if file already exists (first hook call wins; branch won't change
595	    // mid-session and re-writing on every tool call wastes I/O).
596	    if meta_path.exists() {
597	        return Ok(());
598	    }
599	
600	    let meta = serde_json::json!({
601	        "session_id": session_id,
602	        "pr_ref": pr_ref,
603	        "feature_tag": feature_tag,
604	        "captured_at": chrono::Utc::now().to_rfc3339(),
605	    });
606	
607	    std::fs::write(&meta_path, serde_json::to_string(&meta)?)?;
608	    Ok(())
609	}
