611	// ── Provenance capture (diff-on-next-PreToolUse) ───────────────
612	//
613	// Each PreToolUse invocation is a separate OS process. We diff the
614	// working tree against the last snapshot stored in SQLite to detect
615	// what the PREVIOUS tool call changed.
616	
617	fn capture_provenance_best_effort(session_id: &str) {
618	    if std::env::var("RTK_PROVENANCE").as_deref() == Ok("0") {
619	        return;
620	    }
621	    if let Err(e) = capture_provenance(session_id) {
622	        let _ = writeln!(io::stderr(), "[rtk provenance] {e}");
623	    }
624	}
625	
626	fn capture_provenance(session_id: &str) -> Result<()> {
627	    let store = ProvenanceStore::new()?;
628	    let cwd = std::env::current_dir()?;
629	
630	    let tracked_files = collect_tracked_files(&cwd)?;
631	
632	    let mut new_provenance = Vec::new();
633	    for file_path in &tracked_files {
634	        let mtime = file_path
635	            .metadata()
636	            .and_then(|m| m.modified())
637	            .ok();
638	        if let Some(mt) = mtime {
639	            let age = mt.elapsed().unwrap_or_default();
640	            if age.as_secs() > 30 {
641	                continue;
642	            }
643	        }
644	
645	        let rel = file_path
646	            .strip_prefix(&cwd)
647	            .unwrap_or(file_path)
648	            .to_string_lossy()
649	            .replace('\\', "/");
650	
651	        let current_hash = match content_hash::hash_file(file_path) {
652	            Ok(h) => h,
653	            Err(_) => continue,
654	        };
655	
656	        let prev_hash = store.get_snapshot(&rel)?;
657	        if prev_hash.as_deref() == Some(&current_hash) {
658	            continue;
659	        }
660	
661	        if prev_hash.is_some() {
662	            let content = std::fs::read(file_path).unwrap_or_default();
663	            let line_count = content.iter().filter(|&&b| b == b'\n').count() as u32;
664	            let record = provenance::create_signed_record(
665	                &rel,
666	                &content,
667	                1,
668	                line_count.max(1),
669	                session_id,
670	            )?;
671	            new_provenance.push(record);
672	        }
673	
674	        store.save_snapshot(&rel, &current_hash)?;
675	    }
676	
677	    for record in &new_provenance {
678	        store.record_provenance(record)?;
679	    }
680	
681	    Ok(())
682	}
683	
684	fn collect_tracked_files(cwd: &std::path::Path) -> Result<Vec<std::path::PathBuf>> {
685	    let output = std::process::Command::new("git")
686	        .args(["ls-files", "--cached", "--others", "--exclude-standard", "-z"])
687	        .current_dir(cwd)
688	        .output();
689	
690	    let output = match output {
691	        Ok(o) if o.status.success() => o,
692	        _ => return Ok(Vec::new()),
693	    };
694	
695	    let files: Vec<std::path::PathBuf> = output
696	        .stdout
697	        .split(|&b| b == 0)
698	        .filter(|s| !s.is_empty())
699	        .filter_map(|s| std::str::from_utf8(s).ok())
700	        .filter(|s| {
701	            let ext = std::path::Path::new(s)
702	                .extension()
703	                .and_then(|e| e.to_str())
704	                .unwrap_or("");
705	            matches!(
706	                ext,
707	                "rs" | "ts" | "tsx" | "js" | "jsx" | "py" | "go" | "java"
708	                    | "kt" | "swift" | "cs" | "rb" | "sh" | "sql" | "toml"
709	                    | "yaml" | "yml" | "json" | "md"
710	            )
711	        })
712	        .map(|s| cwd.join(s))
713	        .collect();
714	
715	    Ok(files)
716	}
