59	/// Rate limiter tracking last request time per registry.
60	pub(crate) struct RateLimiter {
61	    last_npm: Option<Instant>,
62	    last_pypi: Option<Instant>,
63	    last_crates: Option<Instant>,
64	    min_interval: Duration,
65	}
66	
67	impl RateLimiter {
68	    fn new(rate_per_sec: u32) -> Self {
69	        let interval_ms = if rate_per_sec == 0 {
70	            100
71	        } else {
72	            1000 / rate_per_sec as u64
73	        };
74	        Self {
75	            last_npm: None,
76	            last_pypi: None,
77	            last_crates: None,
78	            min_interval: Duration::from_millis(interval_ms),
79	        }
80	    }
81	
82	    fn throttle(&mut self, registry: Registry) {
83	        let last = match registry {
84	            Registry::Npm => &mut self.last_npm,
85	            Registry::PyPi => &mut self.last_pypi,
86	            Registry::Crates => &mut self.last_crates,
87	        };
88	        if let Some(t) = last {
89	            let elapsed = t.elapsed();
90	            if elapsed < self.min_interval {
91	                std::thread::sleep(self.min_interval - elapsed);
92	            }
93	        }
94	        *last = Some(Instant::now());
95	    }
96	}
