98	/// Persistent cache for dependency validation results.
99	pub struct DepCache {
100	    conn: Connection,
101	    ttl_hours: u64,
102	    offline: bool,
103	}
104	
105	impl DepCache {
106	    pub fn new(ttl_hours: u64, offline: bool) -> Result<Self> {
107	        let db_path = get_cache_db_path()?;
108	        Self::open(&db_path, ttl_hours, offline)
109	    }
110	
111	    pub fn open(db_path: &Path, ttl_hours: u64, offline: bool) -> Result<Self> {
112	        if let Some(parent) = db_path.parent() {
113	            std::fs::create_dir_all(parent)?;
114	        }
115	        let conn = Connection::open(db_path)
116	            .with_context(|| format!("open dep_cache db at {}", db_path.display()))?;
117	        let _ = conn.execute_batch("PRAGMA journal_mode=WAL; PRAGMA busy_timeout=3000;");
118	        conn.execute(
119	            "CREATE TABLE IF NOT EXISTS dep_cache (
120	                id INTEGER PRIMARY KEY,
121	                pkg_name TEXT NOT NULL,
122	                registry TEXT NOT NULL,
123	                pkg_exists INTEGER NOT NULL,
124	                downloads INTEGER,
125	                checked_at TEXT NOT NULL,
126	                UNIQUE(pkg_name, registry)
127	            )",
128	            [],
129	        )?;
130	        conn.execute(
131	            "CREATE INDEX IF NOT EXISTS idx_dep_pkg ON dep_cache(pkg_name, registry)",
132	            [],
133	        )?;
134	        Ok(Self { conn, ttl_hours, offline })
135	    }
136	
137	    /// Returns cached result if within TTL, None otherwise.
138	    pub fn get(&self, pkg: &str, registry: Registry) -> Option<bool> {
139	        let cutoff = chrono::Utc::now()
140	            - chrono::Duration::hours(self.ttl_hours as i64);
141	        let result: rusqlite::Result<(i64, Option<i64>)> = self.conn.query_row(
142	            "SELECT pkg_exists, downloads FROM dep_cache
143	             WHERE pkg_name = ?1 AND registry = ?2 AND checked_at > ?3",
144	            params![pkg, registry.as_str(), cutoff.to_rfc3339()],
145	            |row| Ok((row.get(0)?, row.get(1)?)),
146	        );
147	        result.ok().map(|(e, _)| e != 0)
148	    }
149	
150	    /// Stores a validation result in the cache.
151	    pub fn set(&self, pkg: &str, registry: Registry, pkg_exists: bool, downloads: Option<u64>) {
152	        let now = chrono::Utc::now().to_rfc3339();
153	        let _ = self.conn.execute(
154	            "INSERT OR REPLACE INTO dep_cache (pkg_name, registry, pkg_exists, downloads, checked_at)
155	             VALUES (?1, ?2, ?3, ?4, ?5)",
156	            params![
157	                pkg,
158	                registry.as_str(),
159	                pkg_exists as i64,
160	                downloads.map(|d| d as i64),
161	                now,
162	            ],
163	        );
164	    }
165	
166	    pub fn is_offline(&self) -> bool {
167	        self.offline
168	    }
169	}
