171	/// Parse JS/TS import statements to extract package names.
172	pub fn parse_js_imports(content: &str) -> Vec<String> {
173	    let mut pkgs = Vec::new();
174	
175	    // ES module: import ... from 'pkg' or "pkg"
176	    let from_re = regex::Regex::new(
177	        r#"(?:import|export)\s+(?:[^'"]+\s+from\s+)?['"]([^'"./][^'"]*)['"]\s*"#,
178	    )
179	    .unwrap();
180	    for cap in from_re.captures_iter(content) {
181	        if let Some(m) = cap.get(1) {
182	            pkgs.push(normalize_pkg_name(m.as_str()));
183	        }
184	    }
185	
186	    // CommonJS: require('pkg') or require("pkg")
187	    let req_re =
188	        regex::Regex::new(r#"require\s*\(\s*['"]([^'"./][^'"]*)['"]\s*\)"#).unwrap();
189	    for cap in req_re.captures_iter(content) {
190	        if let Some(m) = cap.get(1) {
191	            pkgs.push(normalize_pkg_name(m.as_str()));
192	        }
193	    }
194	
195	    pkgs.sort();
196	    pkgs.dedup();
197	    pkgs
198	}
