200	/// Parse Python import statements to extract package names.
201	pub fn parse_python_imports(content: &str) -> Vec<String> {
202	    let mut pkgs = Vec::new();
203	
204	    // `import pkg` or `import pkg.sub`
205	    let import_re = regex::Regex::new(r"(?m)^import\s+([a-zA-Z0-9_]+)").unwrap();
206	    for cap in import_re.captures_iter(content) {
207	        if let Some(m) = cap.get(1) {
208	            pkgs.push(m.as_str().to_string());
209	        }
210	    }
211	
212	    // `from pkg import ...`
213	    let from_re = regex::Regex::new(r"(?m)^from\s+([a-zA-Z0-9_]+)").unwrap();
214	    for cap in from_re.captures_iter(content) {
215	        if let Some(m) = cap.get(1) {
216	            pkgs.push(m.as_str().to_string());
217	        }
218	    }
219	
220	    pkgs.sort();
221	    pkgs.dedup();
222	    pkgs
223	}
