225	/// Parse Cargo.toml [dependencies] section to extract crate names.
226	pub fn parse_cargo_deps(content: &str) -> Vec<String> {
227	    let mut pkgs = Vec::new();
228	    let mut in_deps = false;
229	
230	    for line in content.lines() {
231	        let trimmed = line.trim();
232	        if trimmed == "[dependencies]"
233	            || trimmed == "[dev-dependencies]"
234	            || trimmed == "[build-dependencies]"
235	        {
236	            in_deps = true;
237	            continue;
238	        }
239	        if trimmed.starts_with('[') {
240	            in_deps = false;
241	        }
242	        if in_deps {
243	            // pkg = "version" or pkg = { version = "..." }
244	            if let Some(eq_pos) = trimmed.find('=') {
245	                let name = trimmed[..eq_pos].trim();
246	                // Skip workspace = true lines
247	                if !name.is_empty() && !name.contains('.') {
248	                    pkgs.push(name.to_string());
249	                }
250	            }
251	        }
252	    }
253	
254	    pkgs.sort();
255	    pkgs.dedup();
256	    pkgs
257	}
