259	/// Validate a package against the npm registry.
260	pub(crate) fn validate_npm(
261	    pkg: &str,
262	    cache: &DepCache,
263	    limiter: &mut RateLimiter,
264	) -> Result<ValidationResult> {
265	    if let Some(exists) = cache.get(pkg, Registry::Npm) {
266	        return Ok(build_result(pkg, exists, None, None));
267	    }
268	    if cache.is_offline() {
269	        eprintln!("[rtk quality] offline: no cache for npm/{}", pkg);
270	        return Ok(build_result(pkg, true, None, None)); // fail-open
271	    }
272	
273	    limiter.throttle(Registry::Npm);
274	
275	    let url = format!("https://registry.npmjs.org/{}", pkg);
276	    match ureq::get(&url).call() {
277	        Ok(resp) => {
278	            let raw = resp.into_string().unwrap_or_default();
279	            let body: serde_json::Value = serde_json::from_str(&raw).unwrap_or_default();
280	            let downloads = body
281	                .get("dist-tags")
282	                .and_then(|_| None::<u64>); // npm metadata doesn't expose downloads in this endpoint
283	            cache.set(pkg, Registry::Npm, true, downloads);
284	            Ok(build_result(pkg, true, downloads, None))
285	        }
286	        Err(ureq::Error::Status(404, _)) => {
287	            cache.set(pkg, Registry::Npm, false, None);
288	            Ok(build_result(pkg, false, None, None))
289	        }
290	        Err(e) => {
291	            eprintln!("[rtk quality] npm registry error for {}: {}", pkg, e);
292	            Ok(build_result(pkg, true, None, None)) // fail-open on network error
293	        }
294	    }
295	}
