376	fn build_result(
377	    name: &str,
378	    exists: bool,
379	    downloads: Option<u64>,
380	    age_days: Option<u64>,
381	) -> ValidationResult {
382	    let severity = if !exists {
383	        Severity::High
384	    } else if downloads.map(|d| d < 100).unwrap_or(false) {
385	        Severity::Medium
386	    } else {
387	        Severity::Low
388	    };
389	    ValidationResult { exists, name: name.to_string(), downloads, age_days, severity }
390	}
