392	/// Strip scope prefix and sub-path from npm package names.
393	/// e.g. `@scope/pkg` → `@scope/pkg`, `pkg/dist/index` → `pkg`
394	fn normalize_pkg_name(raw: &str) -> String {
395	    // For scoped packages keep @scope/name, strip deeper paths
396	    if raw.starts_with('@') {
397	        let parts: Vec<&str> = raw.splitn(3, '/').collect();
398	        if parts.len() >= 2 {
399	            return format!("{}/{}", parts[0], parts[1]);
400	        }
401	        return raw.to_string();
402	    }
403	    // For unscoped, take only the first path segment
404	    raw.split('/').next().unwrap_or(raw).to_string()
405	}
