61	/// Compute Levenshtein distance using two-row DP (no external dep).
62	pub fn levenshtein(a: &str, b: &str) -> usize {
63	    let a: Vec<char> = a.chars().collect();
64	    let b: Vec<char> = b.chars().collect();
65	    let m = a.len();
66	    let n = b.len();
67	
68	    if m == 0 {
69	        return n;
70	    }
71	    if n == 0 {
72	        return m;
73	    }
74	
75	    let mut prev: Vec<usize> = (0..=n).collect();
76	    let mut curr = vec![0usize; n + 1];
77	
78	    for i in 1..=m {
79	        curr[0] = i;
80	        for j in 1..=n {
81	            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
82	            curr[j] = (curr[j - 1] + 1)
83	                .min(prev[j] + 1)
84	                .min(prev[j - 1] + cost);
85	        }
86	        std::mem::swap(&mut prev, &mut curr);
87	    }
88	
89	    prev[n]
90	}
