92	/// Load the top-packages list for a given ecosystem from the embedded data files.
93	fn load_top_packages(ecosystem: &str) -> HashSet<String> {
94	    let content = match ecosystem {
95	        "npm" => include_str!("../../data/top-packages-npm.txt"),
96	        "pypi" => include_str!("../../data/top-packages-pypi.txt"),
97	        "crates" => include_str!("../../data/top-packages-crates.txt"),
98	        _ => return HashSet::new(),
99	    };
100	    content
101	        .lines()
102	        .map(|l| l.trim().to_lowercase())
103	        .filter(|l| !l.is_empty())
104	        .collect()
105	}
