107	/// Check if a package name is a typosquat of any top package (Levenshtein ≤ 2).
108	pub fn check_typosquat(
109	    pkg: &str,
110	    ecosystem: &str,
111	    file_path: &str,
112	    line: usize,
113	) -> Option<Finding> {
114	    let known = load_top_packages(ecosystem);
115	    let pkg_lower = pkg.to_lowercase();
116	
117	    // Exact match is fine — not a typosquat
118	    if known.contains(&pkg_lower) {
119	        return None;
120	    }
121	
122	    for known_pkg in &known {
123	        let dist = levenshtein(&pkg_lower, known_pkg);
124	        if dist > 0 && dist <= 2 {
125	            return Some(Finding::new(
126	                CheckType::Typosquat,
127	                Severity::High,
128	                file_path,
129	                line,
130	                format!(
131	                    "Package '{}' looks like a typosquat of well-known '{}'",
132	                    pkg, known_pkg
133	                ),
134	                Some(format!("Did you mean '{}'?", known_pkg)),
135	            ));
136	        }
137	    }
138	    None
139	}
