141	/// Patterns for suspicious APIs that indicate code execution or shell injection risk.
142	fn suspicious_api_patterns(file_ext: &str) -> Vec<(Regex, &'static str, Severity)> {
143	    match file_ext {
144	        "js" | "ts" | "jsx" | "tsx" | "mjs" | "cjs" => vec![
145	            (
146	                Regex::new(r"\beval\s*\(").unwrap(),
147	                "eval() executes arbitrary code — AI hallucination risk",
148	                Severity::Critical,
149	            ),
150	            (
151	                Regex::new(r"\bexec\s*\(").unwrap(),
152	                "exec() runs shell commands — verify this is intentional",
153	                Severity::High,
154	            ),
155	            (
156	                Regex::new(r"child_process\s*\.\s*exec\s*\(").unwrap(),
157	                "child_process.exec() runs shell commands with shell=true by default",
158	                Severity::Critical,
159	            ),
160	            (
161	                Regex::new(r"child_process\s*\.\s*execSync\s*\(").unwrap(),
162	                "child_process.execSync() runs shell commands synchronously",
163	                Severity::High,
164	            ),
165	            (
166	                Regex::new(r"\bnew\s+Function\s*\(").unwrap(),
167	                "new Function() is equivalent to eval()",
168	                Severity::Critical,
169	            ),
170	        ],
171	        "py" | "python" => vec![
172	            (
173	                Regex::new(r"\beval\s*\(").unwrap(),
174	                "eval() executes arbitrary Python code",
175	                Severity::Critical,
176	            ),
177	            (
178	                Regex::new(r"\bexec\s*\(").unwrap(),
179	                "exec() executes arbitrary Python code",
180	                Severity::Critical,
181	            ),
182	            (
183	                Regex::new(r"subprocess\s*\.\s*call\s*\([^)]*shell\s*=\s*True").unwrap(),
184	                "subprocess.call(shell=True) exposes shell injection risk",
185	                Severity::Critical,
186	            ),
187	            (
188	                Regex::new(r"subprocess\s*\.\s*run\s*\([^)]*shell\s*=\s*True").unwrap(),
189	                "subprocess.run(shell=True) exposes shell injection risk",
190	                Severity::Critical,
191	            ),
192	            (
193	                Regex::new(r"os\s*\.\s*system\s*\(").unwrap(),
194	                "os.system() runs shell commands — prefer subprocess with shell=False",
195	                Severity::High,
196	            ),
197	            (
198	                Regex::new(r"\bpickle\s*\.\s*loads?\s*\(").unwrap(),
199	                "pickle.load() on untrusted data enables remote code execution",
200	                Severity::High,
201	            ),
202	        ],
203	        "rs" => vec![
204	            (
205	                Regex::new(r"unsafe\s*\{").unwrap(),
206	                "unsafe block in AI-generated Rust code — audit carefully",
207	                Severity::Medium,
208	            ),
209	        ],
210	        _ => vec![],
211	    }
212	}
