214	/// Patterns for hardcoded secrets in any language.
215	fn secret_patterns() -> Vec<(Regex, &'static str)> {
216	    vec![
217	        (
218	            Regex::new(r#"(?i)(api[_-]?key|apikey)\s*[=:]\s*['"]([A-Za-z0-9_\-]{16,})['"]\s*"#)
219	                .unwrap(),
220	            "Hardcoded API key detected",
221	        ),
222	        (
223	            Regex::new(r#"(?i)(secret[_-]?key|secret)\s*[=:]\s*['"]([A-Za-z0-9_\-/+]{16,})['"]\s*"#)
224	                .unwrap(),
225	            "Hardcoded secret key detected",
226	        ),
227	        (
228	            Regex::new(r#"(?i)(password|passwd|pwd)\s*[=:]\s*['"]([^'"]{6,})['"]\s*"#).unwrap(),
229	            "Hardcoded password detected",
230	        ),
231	        (
232	            Regex::new(r#"(?i)(token|auth[_-]?token|bearer)\s*[=:]\s*['"]([A-Za-z0-9_\-\.]{16,})['"]\s*"#)
233	                .unwrap(),
234	            "Hardcoded auth token detected",
235	        ),
236	        (
237	            // AWS access key pattern
238	            Regex::new(r"AKIA[0-9A-Z]{16}").unwrap(),
239	            "AWS Access Key ID pattern detected",
240	        ),
241	        (
242	            // Generic private key header
243	            Regex::new(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----").unwrap(),
244	            "Private key material detected in source file",
245	        ),
246	    ]
247	}
