249	/// Pattern for fabricated HTTP API URLs in strings/comments.
250	fn fabricated_url_pattern() -> Regex {
251	    Regex::new(
252	        r#"https?://(?:api\.|v\d+\.|[a-z]+\.)?[a-z0-9\-]+\.[a-z]{2,}/(?:v\d+/|api/)[a-z0-9_/\-]+"#,
253	    )
254	    .unwrap()
255	}
