257	/// Run all hallucination checks on the given file content.
258	///
259	/// `file_ext` should be the extension without leading dot (e.g. "js", "py", "rs").
260	pub fn detect_hallucinations(content: &str, file_ext: &str, file_path: &str) -> Vec<Finding> {
261	    let mut findings = Vec::new();
262	    let lines: Vec<&str> = content.lines().collect();
263	
264	    // 1. Suspicious API patterns (language-specific)
265	    let api_patterns = suspicious_api_patterns(file_ext);
266	    for (line_num, line_text) in lines.iter().enumerate() {
267	        let lineno = line_num + 1;
268	        for (re, msg, sev) in &api_patterns {
269	            if re.is_match(line_text) {
270	                findings.push(Finding::new(
271	                    CheckType::SuspiciousApi,
272	                    *sev,
273	                    file_path,
274	                    lineno,
275	                    format!("{} (line: {})", msg, line_text.trim()),
276	                    None,
277	                ));
278	            }
279	        }
280	    }
281	
282	    // 2. Hardcoded secrets
283	    let secret_pats = secret_patterns();
284	    for (line_num, line_text) in lines.iter().enumerate() {
285	        let lineno = line_num + 1;
286	        for (re, msg) in &secret_pats {
287	            if re.is_match(line_text) {
288	                findings.push(Finding::new(
289	                    CheckType::HardcodedSecret,
290	                    Severity::Critical,
291	                    file_path,
292	                    lineno,
293	                    format!("{} — use environment variables instead", msg),
294	                    Some("Move secrets to .env or a secrets manager".to_string()),
295	                ));
296	            }
297	        }
298	    }
299	
300	    // 3. Fabricated URLs in comments and string literals
301	    let url_re = fabricated_url_pattern();
302	    for (line_num, line_text) in lines.iter().enumerate() {
303	        let lineno = line_num + 1;
304	        // Only flag URLs inside comments or string literals
305	        let is_comment_or_string = line_text.trim_start().starts_with("//")
306	            || line_text.trim_start().starts_with('#')
307	            || line_text.trim_start().starts_with('*')
308	            || line_text.contains('"')
309	            || line_text.contains('\'')
310	            || line_text.contains('`');
311	
312	        if is_comment_or_string {
313	            for mat in url_re.find_iter(line_text) {
314	                findings.push(Finding::new(
315	                    CheckType::FabricatedUrl,
316	                    Severity::Low,
317	                    file_path,
318	                    lineno,
319	                    format!(
320	                        "API URL '{}' — verify this endpoint actually exists",
321	                        mat.as_str()
322	                    ),
323	                    Some("Test the URL manually before shipping".to_string()),
324	                ));
325	            }
326	        }
327	    }
328	
329	    findings
330	}
