4	/// Check a package's license against the allow/deny lists in config.
5	///
6	/// Returns `Some(Finding)` when the license is denied or unknown,
7	/// `None` when the license is explicitly allowed.
8	pub fn check_license(
9	    pkg_name: &str,
10	    license_id: &str,
11	    denied: &[String],
12	    allowed: &[String],
13	    file_path: &str,
14	) -> Option<Finding> {
15	    let lic = license_id.trim();
16	
17	    if denied.iter().any(|d| d.eq_ignore_ascii_case(lic)) {
18	        return Some(Finding {
19	            check_type: CheckType::HallucinatedDep, // repurposed: license violation
20	            severity: Severity::High,
21	            file_path: file_path.to_string(),
22	            line: 0,
23	            message: format!(
24	                "Package '{}' uses license '{}' which is on the denied list",
25	                pkg_name, lic
26	            ),
27	            suggestion: Some(format!(
28	                "Replace '{}' with a package that uses an approved license ({})",
29	                pkg_name,
30	                allowed.join(", ")
31	            )),
32	        });
33	    }
34	
35	    if allowed.iter().any(|a| a.eq_ignore_ascii_case(lic)) {
36	        return None; // explicitly allowed
37	    }
38	
39	    // Unknown license — warn at Medium so it doesn't block by default
40	    Some(Finding {
41	        check_type: CheckType::HallucinatedDep,
42	        severity: Severity::Medium,
43	        file_path: file_path.to_string(),
44	        line: 0,
45	        message: format!(
46	            "Package '{}' has unknown or unlisted license '{}' — review manually",
47	            pkg_name, lic
48	        ),
49	        suggestion: Some("Check the license on the package's registry page".to_string()),
50	    })
51	}
