55	impl QualityConfig {
56	    /// Load from the first found config file:
57	    /// 1. `data/quality-rules.toml` (project-local)
58	    /// 2. `~/.config/rtk/quality-rules.toml` (user-global)
59	    /// Falls back to Default on any parse error.
60	    pub fn load() -> Self {
61	        let candidates: Vec<PathBuf> = vec![
62	            PathBuf::from("data/quality-rules.toml"),
63	            dirs::config_dir()
64	                .unwrap_or_else(|| PathBuf::from("."))
65	                .join("rtk")
66	                .join("quality-rules.toml"),
67	        ];
68	
69	        for path in &candidates {
70	            if let Ok(content) = std::fs::read_to_string(path) {
71	                if let Ok(cfg) = parse_toml_config(&content) {
72	                    return cfg;
73	                }
74	            }
75	        }
76	
77	        Self::default()
78	    }
