179	/// Run the full quality gate over the given files.
180	pub fn run_gate(files: &[PathBuf], config: &QualityConfig) -> Result<GateResult> {
181	    let cache = DepCache::new(config.cache_ttl_hours, config.offline_mode)
182	        .context("failed to open dep cache")?;
183	    let mut limiter = dep_validator::make_rate_limiter(config.rate_limit_per_sec);
184	
185	    let mut all_findings: Vec<Finding> = Vec::new();
186	    let mut deps_checked: usize = 0;
187	
188	    for file_path in files {
189	        let path_str = file_path.to_string_lossy().to_string();
190	
191	        // Skip ignored paths (glob-style prefix match)
192	        if should_ignore(&path_str, &config.ignore_paths) {
193	            continue;
194	        }
195	
196	        let content = match std::fs::read_to_string(file_path) {
197	            Ok(c) => c,
198	            Err(e) => {
199	                eprintln!("[rtk quality] cannot read {}: {}", path_str, e);
200	                continue;
201	            }
202	        };
203	
204	        let ext = file_path
205	            .extension()
206	            .and_then(|e| e.to_str())
207	            .unwrap_or("")
208	            .to_lowercase();
209	
210	        // --- Hallucination detector ---
211	        let mut hall_findings = hallucination_detector::detect_hallucinations(&content, &ext, &path_str);
212	        all_findings.append(&mut hall_findings);
213	
214	        // --- Dependency validator ---
215	        let (pkgs, registry) = extract_packages_for_file(&content, &ext, file_path);
216	
217	        if let Some(reg) = registry {
218	            for pkg in pkgs {
219	                if config.ignore_packages.iter().any(|ig| ig == &pkg) {
220	                    continue;
221	                }
222	                deps_checked += 1;
223	
224	                // Typosquat check (no network needed)
225	                let ecosystem = match reg {
226	                    dep_validator::Registry::Npm => "npm",
227	                    dep_validator::Registry::PyPi => "pypi",
228	                    dep_validator::Registry::Crates => "crates",
229	                };
230	                if let Some(f) =
231	                    hallucination_detector::check_typosquat(&pkg, ecosystem, &path_str, 0)
232	                {
233	                    all_findings.push(f);
234	                }
235	
236	                // Registry existence check
237	                let result = match reg {
238	                    dep_validator::Registry::Npm => {
239	                        dep_validator::validate_npm(&pkg, &cache, &mut limiter)
240	                    }
241	                    dep_validator::Registry::PyPi => {
242	                        dep_validator::validate_pypi(&pkg, &cache, &mut limiter)
243	                    }
244	                    dep_validator::Registry::Crates => {
245	                        dep_validator::validate_crates(&pkg, &cache, &mut limiter)
246	                    }
247	                };
248	
249	                match result {
250	                    Ok(vr) if !vr.exists => {
251	                        all_findings.push(Finding {
252	                            check_type: CheckType::HallucinatedDep,
253	                            severity: Severity::High,
254	                            file_path: path_str.clone(),
255	                            line: 0,
256	                            message: format!(
257	                                "Package '{}' not found on {} registry — possible AI hallucination",
258	                                pkg, ecosystem
259	                            ),
260	                            suggestion: Some(format!(
261	                                "Verify '{}' exists on {}",
262	                                pkg, ecosystem
263	                            )),
264	                        });
265	                    }
266	                    Err(e) => {
267	                        eprintln!("[rtk quality] registry check failed for {}: {}", pkg, e);
268	                    }
269	                    _ => {}
270	                }
271	            }
272	        }
273	
274	        // License check: scan for inline license declarations in manifest files
275	        if ext == "toml" || ext == "json" {
276	            for lic_id in extract_license_ids(&content) {
277	                if let Some(f) = license_checker::check_license(
278	                    &path_str,
279	                    &lic_id,
280	                    &config.denied_licenses,
281	                    &config.allowed_licenses,
282	                    &path_str,
283	                ) {
284	                    all_findings.push(f);
285	                }
286	            }
287	        }
288	    }
289	
290	    // Build stats
291	    let mut findings_by_severity: HashMap<String, usize> = HashMap::new();
292	    for f in &all_findings {
293	        *findings_by_severity
294	            .entry(f.severity.as_str().to_string())
295	            .or_insert(0) += 1;
296	    }
297	
298	    let passed = !all_findings
299	        .iter()
300	        .any(|f| config.is_blocking(f.severity));
301	
302	    Ok(GateResult {
303	        findings: all_findings,
304	        passed,
305	        stats: GateStats {
306	            files_scanned: files.len(),
307	            deps_checked,
308	            findings_by_severity,
309	        },
310	    })
311	}
312	
313	/// Extract package names and registry from file content based on extension.
314	fn extract_packages_for_file(
315	    content: &str,
316	    ext: &str,
317	    file_path: &Path,
318	) -> (Vec<String>, Option<dep_validator::Registry>) {
319	    match ext {
320	        "js" | "ts" | "jsx" | "tsx" | "mjs" | "cjs" => {
321	            (parse_js_imports(content), Some(dep_validator::Registry::Npm))
322	        }
323	        "py" => (
324	            parse_python_imports(content),
325	            Some(dep_validator::Registry::PyPi),
326	        ),
327	        "toml" => {
328	            // Only parse Cargo.toml files
329	            let name = file_path
330	                .file_name()
331	                .and_then(|n| n.to_str())
332	                .unwrap_or("");
333	            if name == "Cargo.toml" {
334	                (parse_cargo_deps(content), Some(dep_validator::Registry::Crates))
335	            } else {
336	                (vec![], None)
337	            }
338	        }
339	        _ => (vec![], None),
340	    }
341	}
342	
343	/// Extract license identifiers from manifest file content.
344	/// Matches `license = "MIT"` (TOML) and `"license": "MIT"` (JSON).
345	fn extract_license_ids(content: &str) -> Vec<String> {
346	    let re = regex::Regex::new(
347	        r#"(?i)"?license"?\s*[=:]\s*["']([A-Za-z0-9\-\.+]+)["']"#,
348	    )
349	    .unwrap();
350	    re.captures_iter(content)
351	        .filter_map(|c| c.get(1).map(|m| m.as_str().to_string()))
352	        .collect()
353	}
354	
355	/// Simple glob-style ignore: supports `**` prefix patterns.
356	fn should_ignore(path: &str, patterns: &[String]) -> bool {
357	    for pat in patterns {
358	        let pat_clean = pat.trim_start_matches("**/").trim_end_matches("/**");
359	        if path.contains(pat_clean) {
360	            return true;
361	        }
362	    }
363	    false
364	}
