9	/// Run the gate and return the exit code (for main.rs dispatch).
10	pub fn run_gate_with_exit(all: bool, json: bool) -> Result<i32> {
11	    let config = QualityConfig::load();
12	    let files = collect_files(all)?;
13	
14	    if files.is_empty() {
15	        println!("{}", "GATE PASSED: no files to scan".green().bold());
16	        return Ok(0);
17	    }
18	
19	    let result = quality_gate::run_gate(&files, &config)
20	        .context("quality gate execution failed")?;
21	
22	    if json {
23	        print_json(&result);
24	    } else {
25	        print_human(&result, &config);
26	    }
27	
28	    if result.passed {
29	        Ok(0)
30	    } else {
31	        Ok(1)
32	    }
33	}
