43	/// Get git-staged files via `git diff --staged --name-only`.
44	fn collect_staged_files() -> Result<Vec<PathBuf>> {
45	    let output = std::process::Command::new("git")
46	        .args(["diff", "--staged", "--name-only"])
47	        .output();
48	
49	    match output {
50	        Ok(out) if out.status.success() => {
51	            let files: Vec<PathBuf> = String::from_utf8_lossy(&out.stdout)
52	                .lines()
53	                .filter(|l| !l.is_empty())
54	                .map(PathBuf::from)
55	                .filter(|p| p.exists())
56	                .collect();
57	            Ok(files)
58	        }
59	        Ok(_) => {
60	            // git ran but returned non-zero (e.g., not a git repo) — scan nothing
61	            eprintln!("[rtk quality] warning: not in a git repo, use --all to scan all files");
62	            Ok(vec![])
63	        }
64	        Err(e) => {
65	            eprintln!("[rtk quality] warning: git not available: {}", e);
66	            Ok(vec![])
67	        }
68	    }
69	}
70	
71	/// Walk the project directory and collect all scannable files.
72	fn collect_all_project_files() -> Result<Vec<PathBuf>> {
73	    let ignore_dirs = ["node_modules", "vendor", ".git", "target", "dist", "build"];
74	    let scan_exts = ["js", "ts", "jsx", "tsx", "mjs", "cjs", "py", "toml", "rs"];
75	
76	    let mut files = Vec::new();
77	    for entry in walkdir::WalkDir::new(".")
78	        .follow_links(false)
79	        .into_iter()
80	        .filter_entry(|e| {
81	            let name = e.file_name().to_string_lossy();
82	            !ignore_dirs.iter().any(|d| name == *d)
83	        })
84	        .filter_map(|e| e.ok())
85	    {
86	        if !entry.file_type().is_file() {
87	            continue;
88	        }
89	        let ext = entry
90	            .path()
91	            .extension()
92	            .and_then(|e| e.to_str())
93	            .unwrap_or("");
94	        if scan_exts.contains(&ext) {
95	            files.push(entry.path().to_path_buf());
96	        }
97	    }
98	    Ok(files)
99	}
