101	fn print_human(result: &GateResult, config: &QualityConfig) {
102	    if result.findings.is_empty() {
103	        println!(
104	            "{}",
105	            format!(
106	                "GATE PASSED: {} file(s) scanned, 0 findings",
107	                result.stats.files_scanned
108	            )
109	            .green()
110	            .bold()
111	        );
112	        return;
113	    }
114	
115	    // Print findings grouped by severity
116	    println!();
117	    for finding in &result.findings {
118	        print_finding(finding);
119	    }
120	    println!();
121	
122	    // Summary line
123	    let critical = result.stats.findings_by_severity.get("critical").copied().unwrap_or(0);
124	    let high = result.stats.findings_by_severity.get("high").copied().unwrap_or(0);
125	    let medium = result.stats.findings_by_severity.get("medium").copied().unwrap_or(0);
126	    let low = result.stats.findings_by_severity.get("low").copied().unwrap_or(0);
127	
128	    if result.passed {
129	        println!(
