9	/// Run an ad-hoc scan on a specific file.
10	/// `deps_only` — only run dependency checks.
11	/// `security_only` — only run security/hallucination checks.
12	pub fn run_scan(file: Option<&str>, deps_only: bool, security_only: bool) -> Result<i32> {
13	    let config = QualityConfig::load();
14	
15	    let files: Vec<PathBuf> = match file {
16	        Some(f) => {
17	            let p = PathBuf::from(f);
18	            if !p.exists() {
19	                anyhow::bail!("file not found: {}", f);
20	            }
21	            vec![p]
22	        }
23	        None => {
24	            anyhow::bail!("scan requires a file argument (e.g. rtk scan src/main.js)");
25	        }
26	    };
27	
28	    let mut all_findings: Vec<Finding> = Vec::new();
29	
30	    let cache = DepCache::new(config.cache_ttl_hours, config.offline_mode)
31	        .context("failed to open dep cache")?;
32	    let mut limiter = dep_validator::make_rate_limiter(config.rate_limit_per_sec);
33	
34	    for file_path in &files {
35	        let path_str = file_path.to_string_lossy().to_string();
36	        let content = std::fs::read_to_string(file_path)
37	            .with_context(|| format!("cannot read {}", path_str))?;
38	
39	        let ext = file_path
40	            .extension()
41	            .and_then(|e| e.to_str())
42	            .unwrap_or("")
43	            .to_lowercase();
44	
45	        // Security/hallucination checks
46	        if !deps_only {
47	            let mut hall = hallucination_detector::detect_hallucinations(&content, &ext, &path_str);
48	            all_findings.append(&mut hall);
49	        }
50	
51	        // Dependency checks
52	        if !security_only {
53	            let pkgs = extract_packages(&content, &ext, file_path);
54	            let (pkgs, registry) = pkgs;
55	
56	            if let Some(reg) = registry {
57	                let ecosystem = match reg {
58	                    dep_validator::Registry::Npm => "npm",
59	                    dep_validator::Registry::PyPi => "pypi",
60	                    dep_validator::Registry::Crates => "crates",
61	                };
62	
63	                for pkg in pkgs {
64	                    if config.ignore_packages.iter().any(|ig| ig == &pkg) {
65	                        continue;
66	                    }
67	
68	                    // Typosquat check
69	                    if let Some(f) = hallucination_detector::check_typosquat(
70	                        &pkg, ecosystem, &path_str, 0,
71	                    ) {
72	                        all_findings.push(f);
73	                    }
74	
75	                    // Registry existence check
76	                    let result = match reg {
77	                        dep_validator::Registry::Npm => {
78	                            dep_validator::validate_npm(&pkg, &cache, &mut limiter)
79	                        }
80	                        dep_validator::Registry::PyPi => {
81	                            dep_validator::validate_pypi(&pkg, &cache, &mut limiter)
82	                        }
83	                        dep_validator::Registry::Crates => {
84	                            dep_validator::validate_crates(&pkg, &cache, &mut limiter)
85	                        }
86	                    };
87	
88	                    match result {
89	                        Ok(vr) if !vr.exists => {
90	                            all_findings.push(Finding {
91	                                check_type: CheckType::HallucinatedDep,
92	                                severity: Severity::High,
93	                                file_path: path_str.clone(),
94	                                line: 0,
95	                                message: format!(
96	                                    "Package '{}' not found on {} — possible hallucination",
97	                                    pkg, ecosystem
98	                                ),
99	                                suggestion: Some(format!(
100	                                    "Verify '{}' exists on {}",
101	                                    pkg, ecosystem
102	                                )),
103	                            });
104	                        }
105	                        Err(e) => {
106	                            eprintln!("[rtk scan] registry error for {}: {}", pkg, e);
107	                        }
108	                        _ => {}
109	                    }
110	                }
111	            }
112	        }
113	    }
114	
115	    print_scan_results(&all_findings, &config);
116	    Ok(0)
117	}
118	
119	fn extract_packages(
120	    content: &str,
121	    ext: &str,
122	    file_path: &PathBuf,
123	) -> (Vec<String>, Option<dep_validator::Registry>) {
124	    match ext {
125	        "js" | "ts" | "jsx" | "tsx" | "mjs" | "cjs" => (
126	            dep_validator::parse_js_imports(content),
127	            Some(dep_validator::Registry::Npm),
128	        ),
129	        "py" => (
130	            dep_validator::parse_python_imports(content),
131	            Some(dep_validator::Registry::PyPi),
132	        ),
133	        "toml" => {
134	            let name = file_path
135	                .file_name()
136	                .and_then(|n| n.to_str())
137	                .unwrap_or("");
138	            if name == "Cargo.toml" {
139	                (
140	                    dep_validator::parse_cargo_deps(content),
141	                    Some(dep_validator::Registry::Crates),
142	                )
143	            } else {
144	                (vec![], None)
145	            }
146	        }
147	        _ => (vec![], None),
148	    }
149	}
