151	fn print_scan_results(findings: &[Finding], config: &QualityConfig) {
152	    if findings.is_empty() {
153	        println!("{}", "SCAN CLEAN: no findings".green().bold());
154	        return;
155	    }
156	
157	    println!();
158	    for f in findings {
159	        let sev_label = match f.severity {
160	            Severity::Critical => "[CRITICAL]".red().bold().to_string(),
161	            Severity::High => "[HIGH]".yellow().bold().to_string(),
162	            Severity::Medium => "[MEDIUM]".cyan().to_string(),
163	            Severity::Low => "[LOW]".white().dimmed().to_string(),
164	        };
165	
166	        let location = if f.line > 0 {
167	            format!("{}:{}", f.file_path, f.line)
168	        } else {
169	            f.file_path.clone()
170	        };
171	
172	        println!(
173	            "{} [{}] {}",
174	            sev_label,
175	            f.check_type.as_str().dimmed(),
176	            location.bold()
177	        );
178	        println!("  {}", f.message);
179	        if let Some(ref sug) = f.suggestion {
180	            println!("  {} {}", "hint:".dimmed(), sug.dimmed());
181	        }
182	    }
183	
184	    println!();
185	
186	    let blocking = findings.iter().filter(|f| config.is_blocking(f.severity)).count();
187	    if blocking > 0 {
188	        println!(
189	            "{}",
190	            format!("SCAN: {} finding(s), {} blocking", findings.len(), blocking)
191	                .yellow()
192	                .bold()
193	        );
194	    } else {
195	        println!(
196	            "{}",
197	            format!(
198	                "SCAN: {} finding(s), none blocking (use 'rtk gate' for CI enforcement)",
199	                findings.len()
200	            )
201	            .cyan()
202	        );
203	    }
204	}
